/** @file train.h Base for the train class. */

#ifndef TRAIN_H
#define TRAIN_H

#include "core/enum_type.hpp"

#include "newgrf_engine.h"
#include "cargotype.h"
#include "rail.h"
#include "engine_base.h"
#include "rail_map.h"
#include "ground_vehicle.hpp"
#include "pbs.h"

struct Train;
enum ClientID : uint32_t;

/** Rail vehicle flags. */
enum class VehicleRailFlag : uint8_t {
	Reversing                 = 0,  ///< Train is slowing down to reverse.
	WaitingRestriction        = 1,  ///< Train is waiting due to a routing restriction, only valid when VehicleRailFlag::Stuck is also set.
	/* gap, was VRF_HAVE_SLOT */
	PoweredWagon              = 3,  ///< Wagon is powered.
	Flipped                   = 4,  ///< Reverse the visible direction of the vehicle.
	HasHitRoadVehicle         = 5,  ///< Train has hit road vehicle
	AllowedOnNormalRail       = 6,  ///< Electric train engine is allowed to run on normal rail.
	Reversed                  = 7,  ///< Used for vehicle var 0xFE bit 8 (toggled each time the train is reversed, accurate for first vehicle only).
	Stuck                     = 8,  ///< Train can't get a path reservation.
	LeavingStation            = 9,  ///< Train is just leaving a station.
	BreakdownBraking          = 10, ///< Train is braking because it is broken down.
	BreakdownPower            = 11, ///< Train in which the power of one (or more) of the engines is reduced because of a breakdown.
	BreakdownSpeed            = 12, ///< Train has a reduced maximum speed because of a breakdown.
	BreakdownStopped          = 13, ///< Train is stopped because of a breakdown.
	NeedRepair                = 14, ///< Train has a reduced maximum speed because of a critical breakdown.
	JustDecoupled             = 15, ///< Train has just decoupled, reversing is forbidden until it leaves the station.
	BeyondPlatformEnd         = 16,
	NotYetInPlatform          = 17,
	AdvanceInPlatform         = 18,
	ConsistBreakdown          = 19, ///< One or more vehicles in this consist have a breakdown of some sort (breakdown_ctr != 0).
	ConsistSpeedReduction     = 20, ///< One or more vehicles in this consist may be in a depot or on a bridge (may be false positive but not false negative).
	PendingSpeedRestriction   = 21, ///< This vehicle has one or more pending speed restriction changes.
	SpeedAdaptationExempt     = 22, ///< This vehicle is exempt from train speed adaptation.
};
using VehicleRailFlags = EnumBitSet<VehicleRailFlag, uint32_t>;

static constexpr VehicleRailFlags VehicleRailFlagsIsBroken{VehicleRailFlag::BreakdownPower, VehicleRailFlag::BreakdownSpeed, VehicleRailFlag::BreakdownStopped}; ///< Bitmask of all flags that indicate a broken train (braking is not included)

/** Modes for ignoring signals. */
enum TrainForceProceeding : uint8_t {
	TFP_NONE   = 0,    ///< Normal operation.
	TFP_STUCK  = 1,    ///< Proceed till next signal, but ignore being stuck till then. This includes force leaving depots.
	TFP_SIGNAL = 2,    ///< Ignore next signal, after the signal ignore being stuck.
};

/** Flags for Train::ConsistChanged */
enum class ConsistChangeFlag : uint8_t {
	Length, ///< Allow vehicles to change length.
	Capacity, ///< Allow vehicles to change capacity.
	DepotDirection, ///< Normalise depot direction.
	CheckOnly, ///< Only check whether the changes are possible, do not apply them.
	Immutable, ///< Allow changes to immutable properties (e.g. parent properties).
};
/** Bitset of the %ConsistChangeFlag elements. */
using ConsistChangeFlags = EnumBitSet<ConsistChangeFlag, uint8_t>;

static constexpr ConsistChangeFlags CCF_TRACK{}; ///< Valid changes while vehicle is driving, and possibly changing tracks.
static constexpr ConsistChangeFlags CCF_LOADUNLOAD{}; ///< Valid changes while vehicle is loading/unloading.
static constexpr ConsistChangeFlags CCF_AUTOREFIT{ConsistChangeFlag::Capacity}; ///< Valid changes for autorefitting in stations.
static constexpr ConsistChangeFlags CCF_REFIT{ConsistChangeFlag::Length, ConsistChangeFlag::Capacity}; ///< Valid changes for refitting in a depot.
static constexpr ConsistChangeFlags CCF_ARRANGE{ConsistChangeFlag::Length, ConsistChangeFlag::Capacity, ConsistChangeFlag::DepotDirection}; ///< Valid changes for arranging the consist in a depot.
static constexpr ConsistChangeFlags CCF_SAVELOAD{ConsistChangeFlag::Length}; ///< Valid changes when loading a savegame. (Everything that is not stored in the save.)
static constexpr ConsistChangeFlags CCF_ARRANGE_STATION{ConsistChangeFlag::Capacity}; ///< Valid changes for arranging the consist in a station.
static constexpr ConsistChangeFlags CCF_ARRANGE_CHECK{ConsistChangeFlag::Capacity, ConsistChangeFlag::CheckOnly}; ///< Check whether arranging the consist in a station would be possible.

enum RealisticBrakingConstants {
	RBC_BRAKE_FORCE_PER_LENGTH      = 2400,      ///< Additional force-based brake force per unit of train length
	RBC_BRAKE_POWER_PER_LENGTH      = 15000,     ///< Additional power-based brake force per unit of train length (excludes maglevs)
};

uint8_t FreightWagonMult(CargoType cargo);

void CheckTrainsLengths();

void FreeTrainTrackReservation(Train *consist, TileIndex origin = INVALID_TILE, Trackdir orig_td = INVALID_TRACKDIR);

/** Result flags for TryPathReserveWithResultFlags */
enum TryPathReserveResultFlags {
	TPRRF_NONE                  = 0,      ///< No flags
	TPRRF_RESERVATION_OK        = 0x01,   ///< Reservation OK
	TPRRF_REVERSE_AT_SIGNAL     = 0x02,   ///< Reverse at signal
};
DECLARE_ENUM_AS_BIT_SET(TryPathReserveResultFlags)

TryPathReserveResultFlags TryPathReserveWithResultFlags(Train *consist, bool mark_as_stuck = false, bool first_tile_okay = false);

inline bool TryPathReserve(Train *consist, bool mark_as_stuck = false, bool first_tile_okay = false)
{
	return TryPathReserveWithResultFlags(consist, mark_as_stuck, first_tile_okay) & TPRRF_RESERVATION_OK;
}

void DeleteVisibleTrain(Train *v);

void CheckBreakdownFlags(Train *v);
void GetTrainSpriteSize(EngineID engine, uint &width, uint &height, int &xoffs, int &yoffs, EngineImageType image_type);
bool TrainFitStation(const Train *v);

bool TrainOnCrossing(TileIndex tile);
void NormalizeTrainVehInDepot(const Train *u);

/** Flags for TrainCache::cached_tflags */
enum TrainCacheFlags : uint8_t {
	TCF_NONE              = 0,     ///< No flags
	TCF_TILT              = 0x01,  ///< Train can tilt; feature provides a bonus in curves.
	TCF_RL_BRAKING        = 0x02,  ///< Train realistic braking (movement physics) in effect for this vehicle
	TCF_SPD_RAILTYPE      = 0x04,  ///< Train speed varies depending on railtype
	TCF_MOVING_UNIT_START = 0x08,  ///< Start of an articulated unit in the movement direction
	TCF_NO_DRIVING_CAB    = 0x10,  ///< No driving cab in forward direction, restricted speed

	TCF_ACCEL_TYPE_MASK   = 0xC0,  ///< Acceleration type: 0 - 2 for corresponding value, 3 for mixed
};
DECLARE_ENUM_AS_BIT_SET(TrainCacheFlags)

/** Variables that are cached to improve performance and such */
struct TrainCache {
	/** Cached wagon override spritegroup. */
	const struct SpriteGroup *cached_override = nullptr;

	/* cached values, recalculated on load and each time a vehicle is added to/removed from the consist. */
	TrainCacheFlags cached_tflags{};     ///< train cached flags
	uint8_t cached_num_engines = 0;      ///< total number of engines, including rear ends of multiheaded engines
	uint16_t cached_centre_mass = 0;     ///< Cached position of the centre of mass, from the front
	uint16_t cached_braking_length = 0;  ///< Cached effective length used for deceleration force and power purposes
	uint16_t cached_veh_weight = 0;      ///< Cached individual vehicle weight
	uint16_t cached_uncapped_decel = 0;  ///< Uncapped cached deceleration for realistic braking lookahead purposes
	uint8_t cached_deceleration = 0;     ///< Cached deceleration for realistic braking lookahead purposes

	uint8_t user_def_data = 0;           ///< Cached property 0x25. Can be set by Callback 0x36.

	int16_t cached_curve_speed_mod = 0;  ///< curve speed modifier of the entire train
	uint16_t cached_max_curve_speed = 0; ///< max consist speed limited by curves

	bool operator==(const TrainCache &) const = default;

	uint8_t GetCachedAccelType() const { return this->cached_tflags >> 6; }
	void SetCachedAccelType(uint8_t type) { this->cached_tflags |= static_cast<TrainCacheFlags>(type << 6); }
};

/**
 * 'Train' is either a loco or a wagon.
 */
struct Train final : public GroundVehicle<Train, VehicleType::Train> {
	TrackBits track{}; ///< On which track the train currently is.
	VehicleRailFlags flags{};
	TrainCache tcache{};

	/** Link between the two ends of a multiheaded engine. */
	Train *other_multiheaded_part = nullptr;

	std::unique_ptr<TrainReservationLookAhead> lookahead{};

	RailTypes railtypes{}; ///< On which rail types the train can run.
	RailTypes compatible_railtypes{}; ///< With which rail types the train is compatible.

	TrainForceProceeding force_proceed{}; ///< How the train should behave when it encounters next obstacle.
	uint8_t critical_breakdown_count = 0; ///< Counter for the number of critical breakdowns since last service

	/** Ticks waiting in front of a signal, ticks being stuck or a counter for forced proceeding through signals. */
	uint16_t wait_counter = 0;

	uint16_t reverse_distance = 0;
	uint16_t tunnel_bridge_signal_num = 0;
	static constexpr uint8_t TBS_INVALID_DISTANCE = 0xFF;
	uint8_t tunnel_bridge_tile_ctr = 0;
	// 1 byte gap
	uint16_t speed_restriction = 0;
	uint16_t signal_speed_restriction = 0;
	uint16_t crash_anim_pos = 0; ///< Crash animation counter, also used for realistic braking train brake overheating

	/** Create new Train object. @copydoc GroundVehicle::GroundVehicle */
	Train(VehicleID index) : GroundVehicleBase(index) {}
	/** We want to 'destruct' the right class. */
	~Train() override { this->PreDestructor(); }

	friend struct GroundVehicle<Train, VehicleType::Train>; // GroundVehicle needs to use the acceleration functions defined at Train.

	void MarkDirty() override;
	void UpdateDeltaXY() override;
	ExpensesType GetExpenseType(bool income) const override { return income ? ExpensesType::TrainRevenue : ExpensesType::TrainRun; }
	void PlayLeaveStationSound(bool force = false) const override;
	bool IsPrimaryVehicle() const override { return this->IsFrontEngine() || this->IsFrontWagon(); }
	void GetImage(Direction direction, EngineImageType image_type, VehicleSpriteSeq *result) const override;
	int GetDisplaySpeed() const override { return this->gcache.last_speed; }
	int GetDisplayMaxSpeed() const override { return this->vcache.cached_max_speed; }
	Money GetRunningCost() const override;
	int GetCursorImageOffset() const;
	int GetDisplayImageWidth(Point *offset = nullptr) const;
	bool IsInDepot() const override { return this->track == TRACK_BIT_DEPOT; }
	bool Tick() override;
	void OnNewDay() override;
	void OnPeriodic() override;
	uint Crash(bool flooded = false) override;
	Money CalculateCurrentOverallValue() const;
	Trackdir GetVehicleTrackdir() const override;
	TileIndex GetOrderStationLocation(StationID station) override;
	ClosestDepot FindClosestDepot() const override;

	void ReserveTrackUnderConsist() const;

	uint16_t GetCurveSpeedLimit() const;

	void ConsistChanged(ConsistChangeFlags allowed_changes);

	/**
	 * Check whether the consist changes described by #allowed_changes would be possible,
	 * without actually applying any of them. Used e.g. to verify a consist can be
	 * (re)arranged before coupling trains.
	 * @param allowed_changes Which changes are allowed; only #ConsistChangeFlag::Length and
	 *                        #ConsistChangeFlag::Capacity are considered.
	 * @return true if none of the not-allowed properties would change.
	 */
	bool CanConsistChange(ConsistChangeFlags allowed_changes) const;

	struct MaxSpeedInfo {
		int strict_max_speed;
		int advisory_max_speed;
	};

	int UpdateSpeed(MaxSpeedInfo max_speed_info);

	void UpdateAcceleration();

	bool ConsistNeedsRepair() const;

private:
	MaxSpeedInfo GetCurrentMaxSpeedInfoInternal(bool update_state) const;

public:
	MaxSpeedInfo GetCurrentMaxSpeedInfo() const
	{
		return this->GetCurrentMaxSpeedInfoInternal(false);
	}

	MaxSpeedInfo GetCurrentMaxSpeedInfoAndUpdate()
	{
		return this->GetCurrentMaxSpeedInfoInternal(true);
	}

	int GetCurrentMaxSpeed() const override;

	uint8_t GetZPosCacheUpdateInterval() const
	{
		return Clamp<uint16_t>(std::min<uint16_t>(this->gcache.cached_total_length / 4, this->tcache.cached_centre_mass / 2), 2, 32);
	}

	uint32_t CalculateOverallZPos() const;

	bool UsingRealisticBraking() const { return this->tcache.cached_tflags & TCF_RL_BRAKING; }

	/**
	 * Get the next real (non-articulated part and non rear part of dualheaded engine) vehicle in the consist.
	 * @return Next vehicle in the consist.
	 */
	inline Train *GetNextUnit() const
	{
		Train *v = this->GetNextVehicle();
		if (v != nullptr && v->IsRearDualheaded()) v = v->GetNextVehicle();

		return v;
	}

	/**
	 * Get the previous real (non-articulated part and non rear part of dualheaded engine) vehicle in the consist.
	 * @return Previous vehicle in the consist.
	 */
	inline Train *GetPrevUnit()
	{
		Train *v = this->GetPrevVehicle();
		if (v != nullptr && v->IsRearDualheaded()) v = v->GetPrevVehicle();

		return v;
	}

	/** Get the last real (non-articulated part and non rear part of dualheaded engine) vehicle in the consist.
	 * @return The last vehicle in a chain
	 */
	inline Train *GetLastUnit()
	{
		Train *tmp = this;
		while (tmp->GetNextUnit() != nullptr) {
			tmp = tmp->GetNextUnit();
		}
		return tmp;
	}

	/** Is this vehicle the start of a unit, in the moving direction. */
	inline bool IsMovingUnitStart() const
	{
		return this->tcache.cached_tflags & TCF_MOVING_UNIT_START;
	}

	/**
	 * Calculate the offset from this vehicle's center to the following center taking the vehicle lengths into account.
	 * @return Offset from center to center.
	 */
	int CalcNextVehicleOffset() const
	{
		/* For vehicles with odd lengths the part before the center will be one unit
		 * longer than the part after the center. This means we have to round up the
		 * length of the next vehicle but may not round the length of the current
		 * vehicle. */
		uint8_t rounding = this->IsDrivingBackwards() ? 1 : 0;
		return (this->gcache.cached_veh_length + rounding) / 2 + (this->GetMovingNext() != nullptr ? this->GetMovingNext()->gcache.cached_veh_length + 1 - rounding : 0) / 2;
	}

	const Train *GetStationLoadingVehicle() const
	{
		const Train *v = this->GetMovingFront();
		while (v != nullptr && v->flags.Test(VehicleRailFlag::BeyondPlatformEnd)) v = v->GetMovingNext();
		return v;
	}

	Train *GetStationLoadingVehicle()
	{
		return const_cast<Train *>(const_cast<const Train *>(this)->GetStationLoadingVehicle());
	}

	uint16_t GetCargoWeight(uint cargo_amount) const
	{
		if (cargo_amount > 0) {
			CargoSpec::Get(this->cargo_type)->WeightOfNUnitsInTrain(cargo_amount);
			return (CargoSpec::Get(this->cargo_type)->weight * cargo_amount * FreightWagonMult(this->cargo_type)) / 16;
		} else {
			return 0;
		}
	}

	/**
	 * Allows to know the weight value that this vehicle will use (excluding cargo).
	 * @return Weight value from the engine in tonnes.
	 */
	uint16_t GetWeightWithoutCargo() const
	{
		uint16_t weight = 0;

		/* Vehicle weight is not added for articulated parts. */
		if (!this->IsArticulatedPart()) {
			weight += GetVehicleProperty(this, PROP_TRAIN_WEIGHT, RailVehInfo(this->engine_type)->weight);
		}

		/* Powered wagons have extra weight added. */
		if (this->flags.Test(VehicleRailFlag::PoweredWagon)) {
			weight += RailVehInfo(this->gcache.first_engine)->pow_wag_weight;
		}

		return weight;
	}

	/**
	 * Allows to know the weight value that this vehicle will use (cargo only).
	 * @return Weight value from the engine in tonnes.
	 */
	uint16_t GetCargoWeight() const
	{
		return this->GetCargoWeight(this->cargo.StoredCount());
	}

	VehicleAccelerationModel GetAccelerationTypeFromTrack() const;

	/**
	 * Allows to know the acceleration type of a vehicle.
	 * @return Acceleration type of the vehicle.
	 */
	inline VehicleAccelerationModel GetAccelerationType() const
	{
		uint8_t accel_type = this->tcache.GetCachedAccelType();
		if (accel_type == 3) return this->GetAccelerationTypeFromTrack();
		return static_cast<VehicleAccelerationModel>(accel_type);
	}

	inline RailTypes GetIndirectCompatibleRailTypes() const
	{
		/* Use first railtype, indirect_compatible_railtypes also includes indirection via engine railtypes. */
		return GetRailTypeInfo(*this->railtypes.begin())->indirect_compatible_railtypes;
	}

protected: // These functions should not be called outside acceleration code.
	/**
	 * Gets the speed a broken down train (low speed breakdown) is limited to.
	 * @note This value is not cached, because changing cached_max_speed would have unwanted consequences (e.g. in the GUI).
	 * @param v The front engine of the vehicle.
	 * @return The speed the train is limited to.
	 */
	inline uint16_t GetBreakdownSpeed() const
	{
		assert(this->IsFrontEngine());
		uint16_t speed = UINT16_MAX;

		for (const Train *w = this; w != nullptr; w = w->Next()) {
			if (w->breakdown_ctr == 1 && w->breakdown_type == BREAKDOWN_LOW_SPEED) {
				speed = std::min<uint16_t>(speed, w->breakdown_severity);
			}
		}
		return speed;
	}

	/**
	 * Allows to know the power value that this vehicle will use.
	 * @return Power value from the engine in HP, or zero if the vehicle is not powered.
	 */
	inline uint16_t GetPower() const
	{
		/* Power is not added for articulated parts */
		if (!this->IsArticulatedPart() && (this->IsVirtual() || HasPowerOnRail(this->railtypes, GetRailTypeByTrackBit(this->tile, this->track)))) {
			uint16_t power = GetVehicleProperty(this, PROP_TRAIN_POWER, RailVehInfo(this->engine_type)->power);
			/* Halve power for multiheaded parts */
			if (this->IsMultiheaded()) power /= 2;
			return power;
		}

		return 0;
	}

	/**
	 * Returns a value if this articulated part is powered.
	 * @return Power value from the articulated part in HP, or zero if it is not powered.
	 */
	inline uint16_t GetPoweredPartPower() const
	{
		/* For powered wagons the engine defines the type of engine (i.e. railtype) */
		if (this->flags.Test(VehicleRailFlag::PoweredWagon) && (this->IsVirtual() || HasPowerOnRail(this->railtypes, GetRailTypeByTrackBit(this->tile, this->track)))) {
			return RailVehInfo(this->gcache.first_engine)->pow_wag_power;
		}

		return 0;
	}

	/**
	 * Allows to know the weight value that this vehicle will use.
	 * @return Weight value from the engine in tonnes.
	 */
	inline uint16_t GetWeight() const
	{
		return this->GetWeightWithoutCargo() + this->GetCargoWeight();
	}

	/**
	 * Calculates the weight value that this vehicle will have when fully loaded with its current cargo.
	 * @return Weight value in tonnes.
	 */
	uint16_t GetMaxWeight() const override;

	/**
	 * Allows to know the tractive effort value that this vehicle will use.
	 * @return Tractive effort value from the engine.
	 */
	inline uint8_t GetTractiveEffort() const
	{
		return GetVehicleProperty(this, PROP_TRAIN_TRACTIVE_EFFORT, RailVehInfo(this->engine_type)->tractive_effort);
	}

	/**
	 * Gets the area used for calculating air drag.
	 * @return Area of the engine in m^2.
	 */
	inline uint8_t GetAirDragArea() const
	{
		/* Air drag is higher in tunnels due to the limited cross-section. */
		return (this->track & TRACK_BIT_WORMHOLE && this->vehstatus.Test(VehState::Hidden)) ? 28 : 14;
	}

	/**
	 * Gets the air drag coefficient of this vehicle.
	 * @return Air drag value from the engine.
	 */
	inline uint8_t GetAirDrag() const
	{
		return RailVehInfo(this->engine_type)->air_drag;
	}

	/**
	 * Checks the current acceleration status of this vehicle.
	 * @return Acceleration status.
	 */
	inline AccelStatus GetAccelerationStatus() const
	{
		return (this->vehstatus.Test(VehState::Stopped) || this->flags.Any({VehicleRailFlag::Reversing, VehicleRailFlag::Stuck, VehicleRailFlag::BreakdownBraking})) ? AS_BRAKE : AS_ACCEL;
	}

	/**
	 * Calculates the current speed of this vehicle.
	 * @return Current speed in km/h-ish.
	 */
	inline uint16_t GetCurrentSpeed() const
	{
		return this->cur_speed;
	}

	/**
	 * Returns the rolling friction coefficient of this vehicle.
	 * @return Rolling friction coefficient in [1e-4].
	 */
	inline uint32_t GetRollingFriction() const
	{
		/* Rolling friction for steel on steel is between 0.1% and 0.2%.
		 * The friction coefficient increases with speed in a way that
		 * it doubles at 512 km/h, triples at 1024 km/h and so on. */
		return 15 * (512 + this->GetCurrentSpeed()) / 512;
	}

	/**
	 * Gets the maximum speed allowed by the track for this vehicle.
	 * @return Maximum speed allowed.
	 */
	inline uint16_t GetMaxTrackSpeed() const
	{
		return GetRailTypeInfo(GetRailTypeByTrackBit(this->tile, this->track))->max_speed;
	}

	/**
	 * Returns the curve speed modifier of this vehicle.
	 * @return Current curve speed modifier, in fixed-point binary representation with 8 fractional bits.
	 */
	inline int16_t GetCurveSpeedModifier() const
	{
		return GetVehicleProperty(this, PROP_TRAIN_CURVE_SPEED_MOD, RailVehInfo(this->engine_type)->curve_speed_mod, true);
	}

	/**
	 * Checks if the vehicle is at a tile that can be sloped.
	 * @return True if the tile can be sloped.
	 */
	inline bool TileMayHaveSlopedTrack() const
	{
		/* Any track that isn't TRACK_BIT_X or TRACK_BIT_Y cannot be sloped. */
		return this->track == TRACK_BIT_X || this->track == TRACK_BIT_Y;
	}

	/**
	 * Trains can always use the faster algorithm because they
	 * have always the same direction as the track under them.
	 * @return false
	 */
	inline bool HasToUseGetSlopePixelZ()
	{
		return false;
	}

private:
	void UpdateTrainSpeedAdaptationLimitInternal(uint16_t speed);

public:
	inline void UpdateTrainSpeedAdaptationLimit(uint16_t speed)
	{
		if (speed != this->signal_speed_restriction) this->UpdateTrainSpeedAdaptationLimitInternal(speed);
	}

	bool StopFoundAtVehiclePosition() const;

	bool CanLeadTrain() const;

	/**
	 * Set the movement direction of this vehicle chain.
	 * @param d The direction to move.
	 */
	inline void SetMovingDirection(Direction d) { this->direction = this->IsDrivingBackwards() ? ReverseDir(d) : d; }
};

struct TrainDecelerationStats {
	int deceleration_x2;
	int uncapped_deceleration_x2;
	int z_pos;
	const Train *t;

