void ReverseTrainSwapVeh(Train *v, int l, int r)
{
	Train *a, *b;

	/* locate vehicles to swap */
	for (a = v; l != 0; l--) a = a->Next();
	for (b = v; r != 0; r--) b = b->Next();

	if (a != b) {
		/* swap the hidden bits */
		{
			uint16 tmp = (a->vehstatus & ~VS_HIDDEN) | (b->vehstatus & VS_HIDDEN);
			b->vehstatus = (b->vehstatus & ~VS_HIDDEN) | (a->vehstatus & VS_HIDDEN);
			a->vehstatus = tmp;
		}

		Swap(a->track, b->track);
		Swap(a->direction, b->direction);
		Swap(a->x_pos, b->x_pos);
		Swap(a->y_pos, b->y_pos);
		Swap(a->tile,  b->tile);
		Swap(a->z_pos, b->z_pos);

		SwapTrainFlags(&a->gv_flags, &b->gv_flags);

		UpdateStatusAfterSwap(a);
		UpdateStatusAfterSwap(b);
	} else {
		/* Swap GVF_GOINGUP_BIT/GVF_GOINGDOWN_BIT.
		 * This is a little bit redundant way, a->gv_flags will
		 * be (re)set twice, but it reduces code duplication */
		SwapTrainFlags(&a->gv_flags, &a->gv_flags);
		UpdateStatusAfterSwap(a);
	}
}

void ReverseTrainMultiheaded(Train *v)
{
	for (Train *t = v; t != nullptr; t = t->Next()) {
		if (t->IsMultiheaded()) {
			if (t->IsEngine()) {
				t->ClearEngine();
				Swap(t->spritenum, t->other_multiheaded_part->spritenum);
			} else {
				t->SetEngine();
			}
		}
	}
}

void ReverseTrainArticulated(Train *v)
{
	for (Train *t = v; t != nullptr; t = t->GetNextVehicle()) {
		if (t->HasArticulatedPart()) {
			Train *a = t->GetLastEnginePart();
			a->ClearArticulatedPart();
			t->SetArticulatedPart();
			if (t->IsEngine()) {
				t->ClearEngine();
				if (!t->IsPrimaryVehicle()) t->vehstatus &= ~VS_STOPPED;
				a->SetEngine();
				a->vehstatus |= VS_STOPPED;
			}
			if (t->IsWagon()) {
				t->ClearWagon();
				a->SetWagon();
			}
			Swap(t->value, a->value);
			Swap(t->max_age, a->max_age);
			t = a;
		}
	}
}

static Train *ReverseTrainChain(Train *v)
{
	assert(v == v->First());

	Train *new_first = v->Last();
	Train *tmp = v;
	Train *tmp2 = nullptr;
	for (Train *a = v->Next(); a != nullptr; a = a->Next()) {
		tmp->SetNext(tmp2);
		tmp2 = tmp;
		tmp = a;
	}
	tmp->SetNext(tmp2);

	return new_first;
}

void ReverseTrainOrientation(Train *v)
{
	for (Train *t = v; t != nullptr; t = t->Next()) {
		/* Reverse the direction. */
		if (t->track != TRACK_BIT_DEPOT) t->direction = ReverseDir(t->direction);

		ToggleBit(t->flags, VRF_REVERSE_DIRECTION);
	}
}

static Train *ReverseTrainVeh(Train *v)
{
	ReverseTrainArticulated(v);
	ReverseTrainMultiheaded(v);

	Train *new_front = ReverseTrainChain(v);
	if (new_front->IsEngine()) {
		new_front->SetFrontEngine();
	} else {
		new_front->SetFrontWagon();
	}

	ReverseTrainOrientation(new_front);

	if (v == new_front) return v;
	if (v->orders.list != nullptr || OrderList::CanAllocateItem()) {
		DeleteVehicleOrders(new_front, false, new_front->GetNumOrders() != v->GetNumOrders());

		new_front->orders.list = v->orders.list;
		new_front->AddToShared(v);
	}

	if (v->IsFrontEngine()) {
		v->ClearFrontEngine();
	}
	if (v->IsFrontWagon()) {
		v->ClearFrontWagon();
	}

	if (v->vehstatus & VS_STOPPED) {
		new_front->vehstatus |= VS_STOPPED;
		if (v->IsWagon()) v->vehstatus &= ~VS_STOPPED;
	} else {
		new_front->vehstatus &= ~VS_STOPPED;
		if (v->IsEngine()) v->vehstatus |= VS_STOPPED;
	}

	}

	new_front->CopyVehicleConfigAndStatistics(v);
	ChangeVehicleViewports(v->index, new_front->index);
	ChangeVehicleViewWindow(v->index, new_front->index);
	ChangeVehicleNews(v->index, new_front->index);
	DeleteVehicleOrders(v);

	return new_front;
}

/**
 * Check if the vehicle is a train
 * @param v vehicle on tile
 * @return v if it is a train, nullptr otherwise
 */
static Vehicle *TrainOnTileEnum(Vehicle *v, void *)
{
	return (v->type == VEH_TRAIN) ? v : nullptr;
}


/**
 * Checks if a train is approaching a rail-road crossing
 * @param v vehicle on tile
 * @param data tile with crossing we are testing
 * @return v if it is approaching a crossing, nullptr otherwise
 */
static Vehicle *TrainApproachingCrossingEnum(Vehicle *v, void *data)
{
	if (v->type != VEH_TRAIN || (v->vehstatus & VS_CRASHED)) return nullptr;

	Train *t = Train::From(v);

	if (!t->IsPrimaryVehicle()) return nullptr;

	TileIndex tile = *(TileIndex *)data;

	if (TrainApproachingCrossingTile(t) != tile) return nullptr;

	return t;
}


/**
 * Finds a vehicle approaching rail-road crossing
 * @param tile tile to test
 * @return true if a vehicle is approaching the crossing
 * @pre tile is a rail-road crossing
 */
static bool TrainApproachingCrossing(TileIndex tile)
{
	assert(IsLevelCrossingTile(tile));

	DiagDirection dir = AxisToDiagDir(GetCrossingRailAxis(tile));
	TileIndex tile_from = tile + TileOffsByDiagDir(dir);

	if (HasVehicleOnPos(tile_from, &tile, &TrainApproachingCrossingEnum)) return true;

	dir = ReverseDiagDir(dir);
	tile_from = tile + TileOffsByDiagDir(dir);

	return HasVehicleOnPos(tile_from, &tile, &TrainApproachingCrossingEnum);
}


/**
 * Sets correct crossing state
 * @param tile tile to update
 * @param sound should we play sound?
 * @pre tile is a rail-road crossing
 */
void UpdateLevelCrossing(TileIndex tile, bool sound)
{
	assert(IsLevelCrossingTile(tile));

	/* reserved || train on crossing || train approaching crossing */
	bool new_state = HasCrossingReservation(tile) || HasVehicleOnPos(tile, nullptr, &TrainOnTileEnum) || TrainApproachingCrossing(tile);

	if (new_state != IsCrossingBarred(tile)) {
		if (new_state && sound) {
			if (_settings_client.sound.ambient) SndPlayTileFx(SND_0E_LEVEL_CROSSING, tile);
		}
		SetCrossingBarred(tile, new_state);
		MarkTileDirtyByTile(tile);
	}
}


/**
 * Bars crossing and plays ding-ding sound if not barred already
 * @param tile tile with crossing
 * @pre tile is a rail-road crossing
 */
static inline void MaybeBarCrossingWithSound(TileIndex tile)
{
	if (!IsCrossingBarred(tile)) {
		BarCrossing(tile);
		if (_settings_client.sound.ambient) SndPlayTileFx(SND_0E_LEVEL_CROSSING, tile);
		MarkTileDirtyByTile(tile);
	}
}


static void AdvanceWagonsAfterCouple(Train *v)
{
	int difference = v->CalcNextVehicleOffset();
	int diff_x = abs(v->x_pos - v->Next()->x_pos);
	int diff_y = abs(v->y_pos - v->Next()->y_pos);
	int real_diff = max(diff_x, diff_y);
	real_diff = real_diff - difference;

	assert(real_diff >= 0);

	for (int i = 0; i < real_diff; i++) TrainController(v->Next(), nullptr);
}


/**
 * Turn a train around.
 * @param v %Train to turn around.
 */
void ReverseTrainDirection(Train *v)
{
	if (IsRailDepotTile(v->tile)) {
		InvalidateWindowData(WC_VEHICLE_DEPOT, v->tile);
	}

	/* Clear path reservation in front if train is not stuck. */
	if (!HasBit(v->flags, VRF_TRAIN_STUCK)) FreeTrainTrackReservation(v);

	/* Check if we were approaching a rail/road-crossing */
	TileIndex crossing = TrainApproachingCrossingTile(v);

	v = ReverseTrainVeh(v);

	if (IsRailDepotTile(v->tile)) {
		InvalidateWindowData(WC_VEHICLE_DEPOT, v->tile);
	}

	ToggleBit(v->flags, VRF_TOGGLE_REVERSE);

	ClrBit(v->flags, VRF_REVERSING);

	/* recalculate cached data */
	v->ConsistChanged(CCF_TRACK);

	InvalidateWindowClassesData(WC_TRAINS_LIST, 0);

	for (Train *u = v; u != nullptr; u = u->Next()) {
		SwapTrainFlags(&u->gv_flags, &u->gv_flags);

}

bool TrainFitStation(const Train *v)
{
	if (!IsRailStationTile(v->tile)) return false;
	if (!IsRailStationTile(v->Last()->tile)) return false;
	StationID sid = GetStationIndex(v->tile);
	const Station *st = Station::Get(sid);
	int station_length = st->GetPlatformLength(v->tile, DirToDiagDir(ReverseDir(v->direction))) * TILE_SIZE;
	/* vehicle position is in the middle, 
	 * half vehicle size overlap is fine and solve corner case */
	return v->gcache.cached_total_length - (v->gcache.cached_veh_length + 1) / 2 - v->Last()->gcache.cached_veh_length / 2 <= station_length;
}

static bool CanDecouple(Train *v)
{
	if (!TrainFitStation(v)) return false; 
	if (CountVehiclesInVehicles(v) < 2) return false;
	if (v->GetNextUnit() == nullptr) return false;
	//if (!TrainCheckIfLineContinuesAfterStation(v)) return false;
	return true;
}

uint GetDecoupleVehicleAuto(Train *v)
{
	uint engines_front = 0;
	uint engines_back = 0;
	uint pos = 1;
	bool has_wagons = false;
	bool multihead_front = false;
	for (Train *t = v; t != nullptr; t = t->GetNextVehicle(), pos++) {
		if (t->IsEngine()) {
			if (t->IsMultiheaded()) {
				if (multihead_front) {
					return pos;
				}
				multihead_front = true;
			}
			if (has_wagons) {
				engines_back++;
			} else {
				engines_front++;
			}
		} else {
			has_wagons = true;
		}
	}
	if (engines_front > 0 && has_wagons) return engines_front;
	if (engines_back > 0 && has_wagons) return CountVehiclesInVehicles(v) - engines_back;
	return 1;
}

static Train *GetDecoupleVehicle(Train *v)
{
	Order *decouple_order = v->orders.list->GetOrderAt(v->cur_implicit_order_index + 1);
	uint num_decouple = decouple_order->GetNumDecouple();
	if (num_decouple == 0) num_decouple = GetDecoupleVehicleAuto(v);
	Train *ret = v->GetNextVehicle();
	bool multihead_front = v->IsMultiheaded();

	for (uint i = 1; i < num_decouple && ret->GetNextVehicle() != nullptr; i++) {
		if (multihead_front) {
			if (ret->IsRearDualheaded()) multihead_front = false;
		} else {
			if (ret->IsMultiheaded()) multihead_front = true;
		}
		ret = ret->GetNextVehicle();
	}
	if (multihead_front) return nullptr;
	return ret;
}

