/**
 * Trains enters a station, send out a news item if it is the first train, and start loading.
 * @param consist Train that entered the station.
 * @param station Station visited.
 */
static void TrainEnterStation(Train *consist, StationID station)
{
	consist->last_station_visited = station;

	BaseStation *bst = BaseStation::Get(station);

	if (Waypoint::IsExpected(bst)) {
		consist->DeleteUnreachedImplicitOrders();
		UpdateVehicleTimetable(consist, true);
		consist->last_station_visited = station;
		consist->force_proceed = TFP_NONE;
		SetWindowDirty(WindowClass::VehicleView, consist->index);
		consist->current_order.MakeWaiting();
		consist->current_order.SetNonStopType(ONSF_NO_STOP_AT_ANY_STATION);
		consist->cur_speed = 0;
		consist->UpdateTrainSpeedAdaptationLimit(0);
		return;
	}

	Train *u = nullptr;
	uint8_t load_trains = DECOUPLE_NO_LOAD;
	bool want_decouple = consist->current_order.GetDestination() == station && consist->current_order.GetDecouple() == ODF_DECOUPLE;
	Debug(desync, 1, "TrainEnterStation: veh={} st={} tile=({},{}) want_decouple={} ordertype={}", consist->index, station, TileX(consist->tile), TileY(consist->tile), want_decouple, (int)consist->current_order.GetType());
	if (want_decouple) {
		u = DecoupleTrain(consist);
		Debug(desync, 1, "TrainEnterStation: veh={} decoupled u={}", consist->index, u != nullptr ? u->index.base() : -1);
		/* If the front was driving backwards, the decoupled part is in front of it.
		 * Reverse it now so it drives away from the decoupled part, then forbid
		 * reversing until it has left the station. */
		if (consist->vehicle_flags.Test(VehicleFlag::DrivingBackwards)) {
			ReverseTrainDirection(consist);
			consist = consist->First();
		}
		consist->flags.Set(VehicleRailFlag::JustDecoupled);
		/* For the decoupled part, do the opposite: if it is driving forward (towards
		 * the front part), reverse it now so it drives away from the front part, then
		 * forbid reversing until it leaves the station. */
		if (u != nullptr && u != consist) {
			if (!u->vehicle_flags.Test(VehicleFlag::DrivingBackwards)) {
				ReverseTrainDirection(u);
				u = u->First();
			}
			u->flags.Set(VehicleRailFlag::JustDecoupled);
		}
		SplitOrders(consist, u, load_trains);
		Debug(desync, 1, "DecoupleDebug: afterSplit v={} u={} vIdx={}/{} uIdx={}/{} vCur={} uCur={} uStop={} uSpeed={} load={}",
			consist->index, u != nullptr ? u->index.base() : -1,
			consist->cur_implicit_order_index, consist->GetNumOrders(),
			u != nullptr ? u->cur_implicit_order_index : -1, u != nullptr ? u->GetNumOrders() : 0,
			(int)consist->current_order.GetType(), u != nullptr ? (int)u->current_order.GetType() : -1,
			u != nullptr ? u->vehstatus.Test(VehState::Stopped) : false,
			u != nullptr ? u->cur_speed : -1, load_trains);
		u->last_station_visited = station;
		if (u == consist && consist->owner == _local_company) {
			AddVehicleAdviceNewsItem(AdviceType::Order, GetEncodedString(STR_NEWS_ORDER_DECOUPLE_FAILED, consist->index), consist->index);
		}
	} else {
		load_trains = DECOUPLE_LOAD_FIRST;
	}

	/* check if a train ever visited this station before */
	Station *st = Station::From(bst);
	if (!st->had_vehicle_of_type.Test(StationVehicleType::Train)) {
		st->had_vehicle_of_type.Set(StationVehicleType::Train);
		AddVehicleNewsItem(
			GetEncodedString(STR_NEWS_FIRST_TRAIN_ARRIVAL, st->index),
			consist->owner == _local_company ? NewsType::ArrivalCompany : NewsType::ArrivalOther,
			consist->index,
			st->index
		);
		AI::NewEvent(consist->owner, new ScriptEventStationFirstVehicle(st->index, consist->index));
		Game::NewEvent(new ScriptEventStationFirstVehicle(st->index, consist->index));
	}

	if (load_trains & DECOUPLE_LOAD_FIRST) {
		consist->force_proceed = TFP_NONE;
		InvalidateWindowData(WindowClass::VehicleView, consist->index);
		consist->BeginLoading();
	}
	if (u != nullptr && u != consist && (load_trains & DECOUPLE_LOAD_SECOND)) {
		u->force_proceed = TFP_NONE;
		InvalidateWindowData(WindowClass::VehicleView, u->index);
		u->BeginLoading();
	}

	if (load_trains != DECOUPLE_NO_LOAD) {
		TileIndex station_tile = consist->GetStationLoadingVehicle()->tile;
		TriggerStationRandomisation(st, station_tile, StationRandomTrigger::VehicleArrives);
		TriggerStationAnimation(st, station_tile, StationAnimationTrigger::VehicleArrives);
	}
}

/**
 * Check if the vehicle is compatible with the specified tile.
 * @param v The train to check.
 * @param tile The tile to check.
 * @param check_railtype Should we check the railtype for compatibility?
 * @return \c true iff the tile is compatible with the train.
 */
static inline bool CheckCompatibleRail(const Train *v, TileIndex tile, DiagDirection enterdir, bool check_railtype)
{
	return IsInfraTileUsageAllowed(VehicleType::Train, v->owner, tile) &&
			(!check_railtype || v->compatible_railtypes.Test(GetRailTypeByEntryDir(tile, enterdir)));
}

