void ReverseTrainSwapVehicles(Train *v)
{
	int r = CountVehiclesInChain(v) - 1;  // number of vehicles - 1

	/* swap start<>end, start+1<>end-1, ... */
	int l = 0;
	do {
		ReverseTrainSwapVeh(v, l++, r--);
	} while (l <= r);

	for (Train *u = v; u != nullptr; u = u->Next()) {
		UpdateStatusAfterSwap(u);
	}
}

